insert into daraja.questions(theme, question, options, answer_idx, explanation) values
('Upsell', 'Un client commande un gin tonic. Quel est le meilleur upsell ?', '["Lui proposer un deuxième verre tout de suite","Lui proposer un gin premium dans le même cocktail","Lui proposer une bouteille d''eau","Ne rien proposer"]', 1, 'Monter en gamme sur le même produit : le client garde son choix, le ticket augmente.'),
('Upsell', 'Quelle phrase vend le mieux ?', '["Vous voulez autre chose ?","C''est tout ?","Je vous conseille notre cocktail signature, il est parfait avec ce plat","On a aussi des desserts"]', 2, 'Une recommandation précise et personnelle vend mieux qu''une question fermée.'),
('Cross-sell', 'Le cross-sell, c''est…', '["Vendre plus cher le même produit","Proposer un produit complémentaire","Faire une remise","Changer la commande du client"]', 1, 'Cross-sell = produit complémentaire (une entrée, un dessert, un accord). Upsell = version supérieure.'),
('Cross-sell', 'Une table finit son plat principal. Le meilleur moment pour proposer le dessert ?', '["Avec l''addition","Quand tu débarrasses les assiettes","Seulement si on te le demande","Au moment de la commande des entrées"]', 1, 'Au débarrassage, l''attention du client est disponible et la table n''a pas encore décidé de partir.'),
('Vente', 'Combien d''options faut-il idéalement proposer à un client qui hésite ?', '["Une seule","Deux ou trois","Cinq","Toute la carte"]', 1, 'Trop de choix bloque la décision. Deux ou trois options guidées font vendre.'),
('Vente', 'Un client demande « qu''est-ce que vous me conseillez ? ». Tu réponds…', '["Tout est bon","Ça dépend de vous","Vous aimez plutôt frais et acidulé ou rond et boisé ?","Le moins cher"]', 2, 'Une question de goût permet de recommander juste et donne confiance.'),
('Storytelling', 'Le storytelling d''un cocktail sert surtout à…', '["Remplir le silence","Donner de la valeur et justifier le prix","Montrer qu''on connaît la recette","Faire attendre le client"]', 1, 'Une histoire courte transforme une boisson en expérience : le client paie pour ça.'),
('Storytelling', 'Une bonne histoire de cocktail au service dure environ…', '["10 à 20 secondes","2 minutes","5 minutes","Le temps de toute la préparation"]', 0, 'Court, une image forte, un détail sur un ingrédient. Le client doit avoir envie d''en parler à sa table.'),
('Storytelling', 'Que faut-il éviter quand on raconte un produit ?', '["Parler de l''origine d''un ingrédient","Inventer une histoire fausse","Parler du goût","Sourire"]', 1, 'Jamais inventer : un client curieux vérifie, et la confiance est perdue.'),
('Mixologie', 'Quels sont les trois ingrédients d''un Negroni classique ?', '["Gin, vermouth rouge, Campari","Vodka, triple sec, cranberry","Rhum, citron vert, sucre","Gin, tonic, citron"]', 0, 'Gin, vermouth rouge et Campari à parts égales, servi sur glace avec un zeste d''orange.'),
('Mixologie', 'Un Old Fashioned est à base de…', '["Tequila","Whisky (bourbon ou rye)","Gin","Rhum blanc"]', 1, 'Whisky, sucre, bitters, zeste d''orange. Un des plus anciens cocktails.'),
('Mixologie', 'Pourquoi secoue-t-on (shaker) un cocktail avec agrumes ?', '["Pour faire du bruit","Pour bien mélanger, refroidir, diluer et aérer","Pour gagner du temps","Ce n''est pas nécessaire"]', 1, 'Les jus et sirops se mélangent mal en remuant. Le shaker refroidit, dilue et donne de la texture.'),
('Mixologie', 'Un cocktail uniquement à base d''alcools (ex : Martini) se prépare plutôt…', '["Au shaker","Remué au verre à mélange","Au blender","Directement dans le verre sans glace"]', 1, 'On remue pour garder un cocktail limpide et soyeux, sans bulles d''air.'),
('Mixologie', 'Le « dilution » dans un cocktail, c''est…', '["Une erreur","L''eau apportée par la glace, essentielle à l''équilibre","Un sirop","Un type de verre"]', 1, 'La glace qui fond fait partie de la recette : sans dilution, le cocktail est trop fort et déséquilibré.'),
('Mixologie', 'Un Margarita contient…', '["Tequila, liqueur d''orange, citron vert","Rhum, menthe, citron vert","Vodka, citron, sucre","Gin, citron, blanc d''œuf"]', 0, 'Tequila, triple sec (liqueur d''orange) et citron vert, souvent avec bord de sel.'),
('Mixologie', 'Le Mojito est originaire de…', '["Mexique","Cuba","Brésil","Italie"]', 1, 'Cuba : rhum blanc, menthe, citron vert, sucre, eau gazeuse.'),
('Mixologie', 'À quoi servent les bitters (Angostura…) ?', '["À sucrer","À assaisonner et lier les saveurs","À colorer seulement","À remplacer l''alcool"]', 1, 'Quelques traits suffisent : ce sont les épices du bartender.'),
('Mixologie', 'Un sour classique se construit avec…', '["Alcool, agrume, sucre","Alcool, soda, glace","Alcool, lait, sucre","Alcool, café, crème"]', 0, 'Base + acide + sucre. Le blanc d''œuf est une option pour la texture.'),
('50 Best', 'Que récompense le classement The World''s 50 Best Bars ?', '["Les bars les moins chers","Les meilleurs bars du monde selon un jury d''experts","Les plus grands bars","Les bars d''hôtel uniquement"]', 1, 'Un jury international de professionnels vote chaque année. C''est la référence mondiale du bar.'),
('50 Best', 'Ce qui fait un bar de niveau 50 Best, c''est d''abord…', '["Un décor cher","L''hospitalité et l''expérience client autant que les cocktails","Une longue carte","Des prix bas"]', 1, 'Les meilleurs bars du monde sont d''abord des maisons d''accueil : on se souvient de comment on a été reçu.'),
('Service', 'Un client entre. Tu dois le saluer…', '["Quand tu as fini ta tâche","Dans les premières secondes, même d''un regard","Seulement s''il s''approche du bar","Quand il est assis"]', 1, 'Un contact visuel et un sourire tout de suite : le client se sent attendu.'),
('Service', 'Un client se plaint de son cocktail. Première réaction ?', '["Expliquer qu''il est fait selon la recette","Écouter, s''excuser et proposer de le refaire ou de le changer","Appeler le manager sans rien dire","Ignorer"]', 1, 'On ne discute pas le goût d''un client. On écoute et on règle vite.'),
('Service', 'De quel côté sert-on traditionnellement les boissons ?', '["Par la gauche","Par la droite","Peu importe","Par le centre de la table"]', 1, 'Les boissons se servent par la droite du client, là où sont les verres.'),
('Service', 'Pour tenir un verre à pied correctement, on le prend…', '["Par le haut du verre","Par le pied ou la tige","À pleine main","Par le bord"]', 1, 'Jamais de doigts sur le haut du verre : hygiène et température.'),
('Service', 'Retenir le prénom d''un habitué sert à…', '["Rien","Créer de la fidélité et une relation","Le surveiller","Faire plus vite l''addition"]', 1, 'Un client reconnu revient. C''est la base de l''hospitalité.'),
('Valeurs', 'Un collègue est débordé en plein rush. Tu…', '["Continues ton poste uniquement","Proposes ton aide dès que ton poste le permet","Attends que le manager le dise","Te plains"]', 1, 'Une équipe gagne ensemble : le client voit la salle entière, pas ton poste.'),
('Règlement', 'Tu vas être en retard pour ton service. Tu dois…', '["Arriver sans rien dire","Prévenir ton responsable avant le début du service","Prévenir un collègue après","Ne pas venir"]', 1, 'Prévenir avant, toujours. Ça permet de réorganiser le service.'),
('Règlement', 'Le téléphone personnel pendant le service…', '["Libre usage","Rangé, sauf urgence et accord du responsable","Autorisé derrière le bar","Autorisé si pas de client"]', 1, 'Le client doit sentir toute ton attention. Le téléphone reste rangé.'),
('Hygiène', 'Quand faut-il se laver les mains ?', '["Seulement en arrivant","À chaque changement de tâche, après la pause et après avoir touché argent ou déchets","Une fois par heure","Jamais avec des gants"]', 1, 'Mains propres à chaque changement de tâche : règle de base en restauration.'),
('Vente', 'Un client commande « une bière ». Tu réponds…', '["D''accord","Pression ou bouteille ? On a aussi une bière artisanale très fraîche","Laquelle ?","On n''a que ça"]', 1, 'Préciser et proposer mieux en une phrase : c''est vendre sans forcer.');
